#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

std::string formatMarkdown(const std::string& markdown) {
    std::vector<std::string> lines;
    std::string line;
    std::istringstream iss(markdown);
    while (std::getline(iss, line, '\n')) {
        lines.push_back(line);
    }
    std::string html;
    for (const auto& line : lines) {
        html += "<p>" + line + "</p>\n";
    }
    return html;
}

int main() {
    std::string markdown = "This is a markdown formatted text.\n" +
                           "It contains HTML formatted text.\n" +
                           "And it is also HTML formatted text.\n";
    std::string html = formatMarkdown(markdown);
    std::cout << html << std::endl;
    return 0;
}
